const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const placeholder=(label,extra='')=>`<div class="placeholder ${extra}"><span class="plus">＋</span><span>${escape(label)}</span><small>IMAGE PLACEHOLDER</small></div>`;
const visual=(src,label,extra='')=>src?`<div class="placeholder ${extra}"><img src="${escape(src)}" alt="${escape(label)}" style="width:100%;height:100%;object-fit:contain;position:absolute;inset:0"></div>`:placeholder(label,extra);
$('#theme').textContent=ATLAS.theme;$('#pillars').innerHTML=ATLAS.pillars.map(p=>`<div class="pillar"><b>${p[0]}</b><strong>${p[1]}</strong><small>${p[2]}</small></div>`).join('');
$('.branch-nav').innerHTML=ATLAS.branches.map(b=>`<a href="#branch-${b.id}">${b.id} / ${b.en}</a>`).join('');
$('#branches').innerHTML=ATLAS.branches.map(b=>`<section class="branch reveal" id="branch-${b.id}"><div class="branch-header"><div class="branch-heading"><span class="branch-number">${b.id}</span><div><h3>${b.name}</h3><div class="english">${b.en}</div></div></div><p>${b.idea}</p></div><div class="case-grid">${b.cases.map(c=>`<button class="case-card" data-case="${c.id}" aria-label="查看${b.name}：${c.title}">${visual(c.image,'设计结果 · 待填充')}<div class="case-meta"><span>${c.id} / DESIGN CASE</span><em>待填充</em></div><h4>${c.title}</h4><p>${c.description}</p></button>`).join('')}</div></section>`).join('');
const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('in')}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));
const sticky=()=>$('.summary').classList.toggle('visible',window.scrollY>$('.hero').offsetHeight-100);addEventListener('scroll',sticky,{passive:true});sticky();
const dialog=$('#case-dialog');let current=null,lastTrigger=null;
document.querySelectorAll('[data-case]').forEach(btn=>btn.onclick=()=>{lastTrigger=btn;const b=ATLAS.branches.find(b=>b.cases.some(c=>c.id===btn.dataset.case)),c=b.cases.find(c=>c.id===btn.dataset.case);current=c;$('#case-kicker').textContent=b.id+' / '+b.en+' / '+c.id;$('#case-title').textContent=c.title;$('#case-content').innerHTML=`<section id="detail-result"><h3>设计结果与思路</h3>${visual(c.image,'三视图设计成果 · 待填充','result-placeholder')}<p>${escape(c.thinking)}</p></section><section id="detail-refs"><h3>五条参考 · 从哪里来，学习什么</h3><p>每张参考独立记录出处、学习内容与应用位置。</p><div class="refs">${c.references.map(r=>`<div class="ref">${visual(r.image,'参考图片 · 待填充')}<h4>${escape(r.title)}</h4><p><label>出处</label>${r.url?`<a href="${escape(r.url)}" target="_blank" rel="noopener noreferrer">${escape(r.source)}</a>`:escape(r.source)}</p><p><label>学习</label>${escape(r.learn)}</p><p><label>应用</label>${escape(r.application)}</p></div>`).join('')}</div></section><section id="detail-limits"><h3>设计禁区</h3><p>来自当前方向约束；案例专属禁区后续补充。</p><ul class="limit">${b.limits.map(t=>`<li>${escape(t)}</li>`).join('')}</ul></section><section id="detail-checks"><h3>验收标准</h3><p>没有测试证据的项目保持“待测”。</p><table><thead><tr><th>检查项</th><th>通过条件</th><th>状态</th></tr></thead><tbody>${b.checks.map(a=>`<tr><td>${escape(a[0])}</td><td>${escape(a[1])}</td><td class="status">待测</td></tr>`).join('')}<tr><td>通用输出</td><td>2048×1152；固定三机位；整体四边贴合格式参考框。</td><td class="status">待测</td></tr></tbody></table></section><section id="detail-prompt"><h3>生成提示词</h3><pre class="prompt">${escape(c.prompt)}</pre><button class="copy">复制提示词</button></section><section id="detail-log"><h3>工作记录</h3>${c.logs.length?c.logs.map(l=>`<div class="log"><b>${escape(l.date)} · ${escape(l.title)}</b><p>${escape(l.text)}</p></div>`).join(''):'<div class="log"><b>迭代记录 · 待补充</b><p>每轮记录：输入参考、修改目标、生成结果、检查问题与下一步修正。</p></div>'}</section>`;dialog.setAttribute('open','');document.body.style.overflow='';$('#case-content').scrollTop=0;$('#detail-nav a').classList.remove('active');$('#detail-nav a').classList.add('active');$('.copy').onclick=async()=>{try{await navigator.clipboard.writeText(c.prompt);toast('提示词已复制')}catch{toast('复制不可用，请选中文本复制')}};});
function toast(t){$('.toast').textContent=t;$('.toast').classList.add('show');setTimeout(()=>$('.toast').classList.remove('show'),2000)}
$('#close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.body.style.overflow='';lastTrigger?.focus({preventScroll:true})});
document.querySelectorAll('#detail-nav a').forEach(a=>a.onclick=e=>{e.preventDefault();const el=$(a.getAttribute('href'));if(el){$('#case-content').scrollTo({top:el.offsetTop-$('#case-content').offsetTop-15,behavior:'smooth'});document.querySelectorAll('#detail-nav a').forEach(x=>x.classList.toggle('active',x===a))}});


